//! Glyph names and simple-font encodings to text, from `glyphs.txt`
//! (generated by `tools/generate_pdf_glyphs.rb`), parsed once on first use.

#[cfg(test)]
mod tests;

use std::borrow::Cow;
use std::ops::Range;
use std::sync::LazyLock;

use crate::read::span;

static DATA: &str = include_str!("glyphs.txt");

/// The built-in encodings a simple font starts from (ISO 32000-1, Annex D).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BaseEncoding {
    Standard,
    WinAnsi,
    MacRoman,
    Symbol,
    ZapfDingbats,
}

const SECTIONS: [&str; 6] =
    ["STANDARD", "WIN_ANSI", "MAC_ROMAN", "SYMBOL", "ZAPF_DINGBATS", "PRESENTATION"];
const PRESENTATION: usize = 5;

struct Tables {
    /// Every glyph's text, back to back; the tables hold spans of it.
    text: String,
    /// Sorted by name, as the file is.
    names: Vec<(&'static str, Range<u32>)>,
    encodings: [[Range<u32>; 256]; 5],
    /// Presentation forms and their decompositions, sorted by code point.
    presentation: Vec<(u32, Range<u32>)>,
}

static TABLES: LazyLock<Tables> = LazyLock::new(|| {
    let mut tables = Tables {
        text: String::with_capacity(20 * 1024),
        names: Vec::with_capacity(4_600),
        encodings: std::array::from_fn(|_| std::array::from_fn(|_| 0..0)),
        presentation: Vec::with_capacity(1_000),
    };
    let mut section = None;
    for line in DATA.lines() {
        if let Some(name) = line.strip_prefix('@') {
            section = SECTIONS.iter().position(|known| *known == name);
            continue;
        }
        let Some((key, codes)) = line.split_once(';') else { continue };
        let chars = codes
            .split(' ')
            .filter_map(|hex| u32::from_str_radix(hex, 16).ok().and_then(char::from_u32));
        let span = span::append(&mut tables.text, |text| text.extend(chars));
        match section {
            None => tables.names.push((key, span)),
            Some(PRESENTATION) => {
                if let Ok(code) = u32::from_str_radix(key, 16) {
                    tables.presentation.push((code, span));
                }
            }
            Some(index) => {
                if let Ok(code) = key.parse::<u8>() {
                    tables.encodings[index][usize::from(code)] = span;
                }
            }
        }
    }
    tables
});

fn slice(span: &Range<u32>) -> &'static str {
    span::slice(&TABLES.text, span)
}

/// The text of `code` in a base encoding; empty where it is undefined.
pub fn encoded(base: BaseEncoding, code: u8) -> &'static str {
    slice(&TABLES.encodings[base as usize][usize::from(code)])
}

/// A presentation form's plain text (`ﬁ` is `fi`, Arabic contextual forms
/// their letter), `None` for any other character.
pub fn decomposed(ch: char) -> Option<&'static str> {
    if !matches!(ch, '\u{FB00}'..='\u{FDFF}' | '\u{FE70}'..='\u{FEFF}') {
        return None;
    }
    let presentation = &TABLES.presentation;
    let index = presentation.binary_search_by_key(&u32::from(ch), |&(code, _)| code).ok()?;
    Some(slice(&presentation[index].1))
}

/// The text of a glyph name: the glyph lists, then the conventions for
/// names without an entry (ISO 32000-1, 9.10.2, and the AGL specification):
/// `uniXXXX...` and `uXXXX[XX]` code points, a `.suffix` dropped, and `_`
/// joining the components of a ligature.
pub fn named(name: &str) -> Option<Cow<'static, str>> {
    if let Some(text) = listed(name) {
        return Some(Cow::Borrowed(text));
    }
    let base = name.split_once('.').map_or(name, |(base, _)| base);
    if base.is_empty() {
        return None;
    }
    if base.contains('_') {
        let mut text = String::new();
        for part in base.split('_') {
            text.push_str(&component(part)?);
        }
        return Some(Cow::Owned(text));
    }
    component(base)
}

/// A name's text in the glyph lists.
fn listed(name: &str) -> Option<&'static str> {
    let names = &TABLES.names;
    let index = names.binary_search_by(|(known, _)| known.as_bytes().cmp(name.as_bytes())).ok()?;
    Some(slice(&names[index].1))
}

fn component(name: &str) -> Option<Cow<'static, str>> {
    if let Some(text) = listed(name) {
        return Some(Cow::Borrowed(text));
    }
    let hex = |digits: &str| {
        u32::from_str_radix(digits, 16)
            .ok()
            .filter(|&code| !(0xD800..0xE000).contains(&code))
            .and_then(char::from_u32)
    };
    if let Some(digits) = name.strip_prefix("uni")
        && !digits.is_empty()
        && digits.len().is_multiple_of(4)
        && upper_hex(digits)
    {
        return digits
            .as_bytes()
            .chunks(4)
            .map(|chunk| std::str::from_utf8(chunk).ok().and_then(hex))
            .collect::<Option<String>>()
            .map(Cow::Owned);
    }
    if let Some(digits) = name.strip_prefix('u')
        && (4..=6).contains(&digits.len())
        && upper_hex(digits)
    {
        return hex(digits).map(|ch| Cow::Owned(ch.to_string()));
    }
    None
}

/// Hexadecimal digits in upper case, as `uniXXXX` names spell them.
fn upper_hex(digits: &str) -> bool {
    digits.bytes().all(|byte| byte.is_ascii_digit() || (b'A'..=b'F').contains(&byte))
}

/// Text fit for output: ligatures spelled out and presentation forms as
/// their letters (see [`decomposed`]), no-break and other spaces as
/// spaces, soft hyphens and control characters dropped, the private-use
/// bullets of Symbol and Wingdings fonts as bullets.
pub fn push_clean(out: &mut String, text: &str) {
    for ch in text.chars() {
        if let Some(plain) = decomposed(ch) {
            out.push_str(plain);
            continue;
        }
        match ch {
            '\u{A0}' | '\u{2000}'..='\u{200A}' | '\u{202F}' | '\u{3000}' | '\t' => out.push(' '),
            '\u{F0B7}' | '\u{F06C}' | '\u{F0A7}' | '\u{F0D8}' | '\u{F076}' | '\u{F0FC}' => {
                out.push('•');
            }
            '\u{AD}' | '\u{200B}'..='\u{200F}' | '\u{FEFF}' | '\u{FFFD}' => {}
            ch if ch.is_control() => {}
            ch => out.push(ch),
        }
    }
}
